    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'LOGO-PACK', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[0].qty, 3);
});

test('addLine validates qty', () => {
